package com.yihe.framework.ehr;
import java.util.*;import com.fasterxml.jackson.databind.ObjectMapper;import static com.yihe.framework.ehr.EhrAccess.*;import static com.yihe.framework.ehr.EhrService.*;
public class AiHealthReportChecks{
 static int checks;static void check(String name,boolean ok){if(!ok)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}static void invalid(String name,Map<String,Object> value,Map<String,Object> source)throws Exception{try{AiHealthReport.parse(new ObjectMapper().writeValueAsString(value),source);throw new AssertionError(name);}catch(EhrException e){check(name,"AI_ASSESSMENT_FORMAT_INVALID".equals(e.getMessage()));}}
 public static void main(String[] args)throws Exception{
  Map<String,Object> item=map("id","i-1","name","指标甲","value","8.1","unit","mmol/L","referenceRange","3–6","page",2,"abnormal","H"),other=map("id","i-2","name","指标乙","value","7","unit","mmol/L","referenceRange","1–5","page",3,"abnormal","H");
  Map<String,Object> source=map("person",map("name","测试职工","code","TEST-1"),"report",map("id","r-1","revision",1,"examDate","2026-01-01","items",Arrays.asList(item,other)),"history",Collections.emptyList());AiExamChecks.Fake fake=new AiExamChecks.Fake();Map<String,Object> response=fake.generate(map("task_type","health_assessment","archive_context",AiHealthReport.modelSource(source)));String raw=str(response.get("output"));Map<String,Object> wire=new ObjectMapper().readValue(raw,Map.class);Map<String,Object> result=AiHealthReport.parse(raw,source);check("complete_structured_assessment_is_accepted",AiHealthReport.FORMAT.equals(result.get("schema_version")));String plain=AiHealthReport.plain(result,source);check("original_result_and_page_are_server_resolved",plain.contains("8.1 mmol/L")&&plain.contains("原件第2页"));check("suggestion_is_clearly_unreviewed",plain.contains("待医生确认"));
  Map<String,Object> unknown=new LinkedHashMap<>(wire);unknown.put("suggested_risk","unknown");invalid("new_assessment_requires_explicit_risk_suggestion",unknown,source);check("clinical_results_are_assessable",AiHealthReport.hasUsableResults(source));check("empty_or_unreadable_results_are_not_forced_into_risk_grade",!AiHealthReport.hasUsableResults(map("report",map("items",Arrays.asList(map("name","血糖","value","未识别"))))));
  Map<String,Object> bad=new LinkedHashMap<>(wire);bad.put("suggested_risk","diagnosed");invalid("invalid_risk_enum_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.remove("history_analysis");invalid("missing_report_module_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.put("indicator_analysis",Arrays.asList(map("item_id","invented","analysis","错误引用")));invalid("invented_indicator_reference_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.put("indicator_analysis",Arrays.asList(map("item_id","OBS-C-0001","analysis","仅分析一项")));invalid("omitted_abnormal_indicator_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.put("indicator_analysis",Arrays.asList(map("item_id","OBS-C-0001","analysis","一"),map("item_id","OBS-C-0001","analysis","二")));invalid("duplicate_indicator_reference_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.put("recommendations",Collections.emptyList());invalid("missing_actionable_suggestions_rejected",bad,source);bad=new LinkedHashMap<>(wire);bad.put("unsafe_action","send_message");invalid("unexpected_action_field_rejected",bad,source);
  check("normal_marker_does_not_become_abnormal",!AiHealthReport.abnormal(map("abnormal","正常")));check("abnormal_marker_is_detected",AiHealthReport.abnormal(map("abnormal","异常")));Map<String,Object> modelSource=AiHealthReport.modelSource(source);check("required_abnormal_ids_are_explicit",((List<?>)modelSource.get("requiredIndicatorIds")).size()==2);
  Map<String,Object> duplicateItem=new LinkedHashMap<>(item);duplicateItem.put("id","i-3");duplicateItem.put("page",4);Map<String,Object> repeatedSource=new LinkedHashMap<>(source);Map<String,Object> repeatedReport=new LinkedHashMap<>((Map<String,Object>)source.get("report"));repeatedReport.put("items",Arrays.asList(item,other,duplicateItem));repeatedSource.put("report",repeatedReport);Map<String,Object> compacted=(Map<String,Object>)AiHealthReport.modelSource(repeatedSource).get("report");check("identical_repeated_observations_are_compacted",((List<?>)compacted.get("items")).size()==2&&num(compacted.get("originalItemCount"))==3);check("compacted_observation_keeps_source_pages",((List<?>)((Map<?,?>)((List<?>)compacted.get("items")).get(0)).get("sourcePages")).size()==2);check("compaction_does_not_mutate_archive_snapshot",((List<?>)repeatedReport.get("items")).size()==3);
  Map<String,Object> schema=AiHealthReport.schema();check("schema_rejects_unknown_properties",Boolean.FALSE.equals(schema.get("additionalProperties")));check("policy_has_history_and_exposure_constraints",AiHealthReport.policy().contains("无历史")&&AiHealthReport.policy().contains("暴露浓度"));System.out.println("PASS structured health assessment checks: "+checks);
 }
}
